const business={timezone:'Europe/Skopje',today,lastDate:plus(today,30),profile:'simulated',leadMinutes:1440,bufferBefore:15,bufferAfter:15,horizonDays:30,intervalMinutes:15,syntheticOnly:true};
let records=JSON.parse(localStorage.getItem('kindred-preview-records')||'{}');let attempts=0;
const respond=(d,status=200)=>Promise.resolve(new Response(JSON.stringify(d),{status,headers:{'Content-Type':'application/json'}}));
const save=()=>localStorage.setItem('kindred-preview-records',JSON.stringify(records));
function slots(date){
 if(scenario==='empty'||[0,6].includes(new Date(date+'T12:00Z').getUTCDay())||date<plus(today,2))return [];
 // Illustrative future weekdays, EU UTC offset computed from the chosen date.
 const offset=new Intl.DateTimeFormat('en',{timeZone:'Europe/Skopje',timeZoneName:'shortOffset'}).formatToParts(new Date(date+'T12:00Z')).find(x=>x.type==='timeZoneName').value.includes('+2')?2:1;
 return ['10:15','10:30','11:00','11:30','14:15','15:00','15:45','16:45'].map(label=>({label,startsAt:new Date(date+'T'+label+':00+'+String(offset).padStart(2,'0')+':00').toISOString()}));
}
globalThis.fetch=async(input,options={})=>{
 const url=new URL(String(input),location.origin);if(!url.pathname.startsWith('/api/'))return realFetch(input,options);
 if(options.signal?.aborted)throw new DOMException('Aborted','AbortError');
 if(scenario==='loading')await new Promise(r=>setTimeout(r,2500));
 if(url.pathname==='/api/services')return respond({services:scenario==='no-services'?[]:[service],business});
 if(url.pathname==='/api/slots')return scenario==='availability-error'?respond({error:'Preview availability failed. Retry the request.'},503):respond({date:url.searchParams.get('date'),timezone:business.timezone,slots:slots(url.searchParams.get('date'))});
 if(url.pathname==='/api/bookings'&&options.method==='POST'){
  if(scenario==='conflict')return respond({code:'slot_unavailable',error:'This time was just reserved. Choose another time; your details are kept.'},409);
  const payload=JSON.parse(options.body);const key=options.headers['Idempotency-Key'];let entry=Object.values(records).find(x=>x.key===key);
  if(!entry){const id=crypto.randomUUID();entry={key,accessToken:'a'.repeat(64),booking:{id,reference:'PREVIEW-'+id.slice(0,6),status:'confirmed',startsAt:payload.startsAt,endsAt:new Date(Date.parse(payload.startsAt)+3600000).toISOString(),name:payload.name,email:payload.email,timezone:business.timezone,service,price:1400,currency:'MKD'}};records[id]=entry;save();}
  if(scenario==='unresolved'&&!entry.interrupted){entry.interrupted=true;save();throw Error('Simulated interrupted response after preview persistence');}
  return respond({booking:entry.booking,accessToken:entry.accessToken});
 }
 const match=url.pathname.match(/^\/api\/bookings\/([^/]+)(\/cancel)?$/);
 if(match){const entry=records[match[1]];if(!entry)return respond({error:'No preview booking found'},404);if(options.headers?.Authorization!=='Bearer '+entry.accessToken)return respond({error:'Preview authorization failed'},403);
 if(match[2]){if(scenario==='late-cancellation')return respond({booking:entry.booking,ownerRequest:true,message:'Late cancellation request recorded. Your appointment remains reserved until the fictional owner handles it.'},202);entry.booking.status='cancelled';save();}return respond({booking:entry.booking});}
 return respond({error:'Unsupported preview endpoint'},404);
};

public/styles.css:
:root {
  --ink: #183d35;
  --muted: #52665e;
  --paper: #fcfaf6;
  --line: #d7dfd5;
  --accent: #235143;
  --soft: #e7eddf;
  --radius: 18px;
  --space: 24px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background: #e9ece5;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
textarea,
select {
  font: inherit;
}
button {
  cursor: pointer;
  min-height: 48px;
}
button:disabled {
  cursor: default;
  opacity: 0.48;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid #956331;
  outline-offset: 3px;
}
.workspace {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 64px;
  padding: 56px 24px;
}
.review-panel {
  width: 280px;
  padding-top: 36px;
}
.review-panel p,
.review-panel li {
  font-size: 0.875rem;
  line-height: 1.65;
}
.review-panel ul {
  padding-left: 20px;
}
.review-panel a {
  display: block;
  color: var(--ink);
  margin-top: 24px;
}
.phone {
  width: 390px;
  max-width: 100%;
  background: var(--paper);
  border: 1px solid #ccd5ca;
  border-radius: 32px;
  box-shadow: 0 24px 60px #24403218;
  overflow: hidden;
  padding-top: env(safe-area-inset-top);
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
}
.back {
  border: 0;
  background: transparent;
  font-size: 1.4375rem;
  width: 48px;
}
.brand {
  font-family: Manrope, sans-serif;
  font-weight: 800;
  font-size: 1.5625rem;
  letter-spacing: -1px;
}
.step {
  font-size: 0.75rem;
  color: var(--muted);
  min-width: 3rem;
  white-space: nowrap;
  text-align: right;
}
nav {
  padding: 0 24px 18px;
}
.progress {
  height: 3px;
  background: #dce1d6;
  flex: 1;
  border-radius: 8px;
}
.progress.active {
  background: var(--accent);
}
.screen {
  padding: 0 var(--space) 24px;
  min-height: 610px;
}
.eyebrow {
  display: block;
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 1.7px;
  margin: 20px 0 12px;
  color: var(--muted);
}
h1 {
  font-family: Manrope, sans-serif;
  font-size: 2rem;
  line-height: 1.16;
  letter-spacing: -1.1px;
  margin: 0 0 16px;
  font-weight: 700;
}
h2 {
  font-size: 1rem;
  letter-spacing: -0.3px;
  margin: 24px 0 14px;
}
p {
  font-size: 0.875rem;
  line-height: 1.65;
  color: var(--muted);
  margin: 0 0 20px;
}
.hero {
  padding: 4px 22px 12px;
  background: var(--soft);
  border-radius: var(--radius);
  position: relative;
  overflow: hidden;
}
.hero h1 {
  max-width: 220px;
  font-size: 1.9375rem;
}
.hero p {
  max-width: 235px;
  font-size: 0.8125rem;
}
.hero-art {
  position: absolute;
  right: -10px;
  bottom: 0;
  font-size: 7.1875rem;
  color: #698c6245;
}
.section-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.section-heading span {
  font-size: 0.6875rem;
  color: var(--muted);
}
.service-card {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 17px 14px;
  border: 1px solid var(--line);
  background: transparent;
  border-radius: var(--radius);
  text-align: left;
  margin-bottom: 10px;
  color: var(--ink);
}
.service-icon {
  display: grid;
  place-items: center;
  background: var(--soft);
  border-radius: 12px;
  min-width: 46px;
  height: 52px;
  font-size: 1.875rem;
}
.service-copy {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.service-copy small {
  font-size: 0.5rem;
  letter-spacing: 1px;
  color: var(--muted);
}
.service-copy strong {
  font-size: 1rem;
}
.service-copy span {
  font-size: 0.75rem;
  color: var(--muted);
}
.footnote {
  font-size: 0.6875rem;
  line-height: 1.6;
  margin-top: 18px;
}
.detail-art {
  height: 170px;
  border-radius: var(--radius);
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 70% 20%, #dee9ca, #e9dfcf);
  font-size: 6.875rem;
  color: #466347;
}
.summary {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 18px;
  background: var(--soft);
  border-radius: 14px;
  font-size: 0.875rem;
  margin: 20px 0;
}
.summary small {
  display: block;
  font-size: 0.6875rem;
  color: var(--muted);
  margin-top: 6px;
}
.visit {
  font-size: 0.8125rem;
  color: var(--muted);
  padding-left: 18px;
  line-height: 2;
}
.info {
  border: 1px solid var(--line);
  padding: 16px;
  border-radius: 14px;
  font-size: 0.75rem;
  margin: 20px 0;
  line-height: 1.6;
}
.info small {
  display: block;
  color: var(--muted);
}
.primary {
  width: 100%;
  border: 0;
  border-radius: 14px;
  background: var(--accent);
  color: white;
  font-weight: 600;
  padding: 16px;
  margin-top: 14px;
}
.secondary {
  padding: 12px 18px;
  border: 1px solid var(--accent);
  border-radius: 12px;
  background: transparent;
  color: var(--ink);
}
.days,
.times {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.choice {
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  border-radius: 12px;
  font-size: 0.75rem;
  padding: 12px 4px;
}
.selected {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}
.state {
  padding: 24px 18px;
  border: 1px dashed #adb9a6;
  border-radius: 14px;
  margin: 14px 0;
}
.state h2 {
  margin-top: 0;
}
.state p {
  margin-bottom: 12px;
}
.field {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  margin: 18px 0;
}
.field input,
.field textarea,
.field select {
  display: block;
  /* Keep Safari from zooming the viewport when a form field receives focus. */
  font-size: 1rem;
  width: 100%;
  padding: 14px 12px;
  background: white;
  border: 1px solid #adbcae;
  border-radius: 12px;
  margin-top: 8px;
  color: var(--ink);
  min-height: 48px;
}
.field textarea {
  min-height: 90px;
  resize: vertical;
}
.error {
  display: block;
  color: #a12c21;
  margin-top: 7px;
  font-size: 0.75rem;
}
.error-box {
  background: #fff0ec;
  border: 1px solid #d9a89d;
  border-radius: 12px;
  padding: 14px;
  font-size: 0.75rem;
  color: #882b21;
}
.booking-time {
  font-weight: 600;
  color: var(--ink);
}
.check {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--soft);
  font-size: 2rem;
  margin: 28px 0;
}
.confirmation {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 4px 16px 18px;
  margin: 24px 0;
}
.confirmation .summary {
  padding: 14px 0;
  background: none;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}
.confirmation p {
  font-size: 0.8125rem;
  margin: 10px 0;
}
.confirmation small {
  font-size: 0.625rem;
  color: var(--muted);
}
footer {
  text-align: center;
  font-size: 0.5rem;
  letter-spacing: 1.2px;
  padding: 12px 12px calc(20px + env(safe-area-inset-bottom));
  color: var(--muted);
  border-top: 1px solid var(--line);
}
.draft .phone {
  --radius: 4px;
  --soft: #eee;
  --accent: #344a45;
  font-family: Arial, sans-serif;
}
.draft .phone h1 {
  font-family: Arial, sans-serif;
  font-size: 1.6875rem;
  letter-spacing: 0;
}
.draft .service-card {
  gap: 8px;
  padding: 10px 8px;
}
.draft .service-icon {
  display: none;
}
.draft .hero {
  background: #eee;
}
.draft .hero-art {
  display: none;
}
.draft .summary,
.draft .primary,
.draft .choice {
  border-radius: 4px;
}
.draft .section-heading span {
  display: none;
}
@media (max-width: 720px) {
  .workspace {
    display: block;
    padding: 0;
    background: var(--paper);
  }
  .phone {
    width: 390px;
    margin: auto;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
  .review-panel {
    width: 100%;
    max-width: 390px;
    margin: auto;
    padding: 20px 24px;
    border-bottom: 1px solid var(--line);
  }
  .review-panel h2 {
    margin-top: 8px;
  }
  .review-panel p,
  .review-panel ul {
    display: none;
  }
  .review-panel .field {
    display: inline-block;
    width: 48%;
    vertical-align: top;
    margin: 10px 0;
  }
  .review-panel .field + .field {
    margin-left: 4%;
  }
  .review-panel small {
    display: block;
    font-size: 0.625rem;
  }
  .review-panel a {
    font-size: 0.75rem;
    margin: 12px 0 0;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .screen {
    animation: appear 0.2s ease-out;
  }
  @keyframes appear {
    from {
      opacity: 0.6;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}

/* Explicit mobile panel grid keeps controls separated even with intervening content. */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 720px) {
  .review-panel {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    column-gap: 12px;
  }
  .review-panel > * {
    grid-column: 1 / -1;
  }
  .review-panel .field {
    grid-column: auto;
    grid-row: 3;
    display: block;
    width: 100%;
    min-width: 0;
  }
  .review-panel .field + .field {
    margin-left: 0;
  }
}

.progress-list { display: flex; gap: 5px; list-style: none; padding: 0; margin: 0; }

.booking-status { margin: 16px 0; }
.date-input { width: 100%; min-height: 48px; }
.retry-actions { display: flex; gap: 12px; flex-wrap: wrap; }

public/design.css:
/* Generated from booking-design-workflow/design-tokens.json. */
:root[data-design="calm-spa"] {--ink:#243d35;--muted:#52645b;--paper:#fffdf8;--line:#d6dfd5;--accent:#244f40;--soft:#eaf0e4;--canvas:#e6ebe4;--radius:22px;--space:24px;--heading:Georgia, serif;background:var(--canvas);}
:root[data-design="clean-clinic"] {--ink:#15364c;--muted:#486271;--paper:#ffffff;--line:#cddde6;--accent:#165b7a;--soft:#eaf5fa;--canvas:#e7eff4;--radius:10px;--space:24px;--heading:system-ui, sans-serif;background:var(--canvas);}
:root[data-design="modern-boutique"] {--ink:#3e2947;--muted:#67566e;--paper:#fffafc;--line:#e6d6e1;--accent:#693855;--soft:#f4e6ed;--canvas:#efe6ee;--radius:16px;--space:24px;--heading:Georgia, serif;background:var(--canvas);}

.brand,h1 {font-family:var(--heading,Georgia,serif)}
.brand {letter-spacing:-1.1px;font-weight:600}
h1 {font-weight:500;line-height:1.15;font-size:2.15rem}
.hero {padding:18px 22px 20px;background:linear-gradient(140deg,var(--soft),var(--paper));border:1px solid var(--line)}
.hero h1 {font-size:2.1rem;max-width:240px}
.eyebrow {font-size:.68rem;letter-spacing:1.4px}
.service-copy small,footer {font-size:.68rem}
.service-card {background:var(--paper);padding:20px 16px;box-shadow:0 4px 16px #243d3508}
.detail-art {background:var(--soft);border:1px solid var(--line)}
.phone {border-color:var(--line)}
.primary {border-radius:var(--radius);box-shadow:0 4px 12px #243d3518}
.primary:hover:not(:disabled) {filter:brightness(1.12)}
.choice:hover:not(:disabled):not(.selected) {background:var(--soft)}
.field input,.field select,.field textarea {border-color:var(--line)}
form>label:not(.field) {display:block;font-size:.8rem;font-weight:600}
form>label:not(.field)>select {display:block;min-height:48px;width:100%;margin:8px 0 14px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink);font-size:1rem}
:root[data-design="clean-clinic"] h1 {font-weight:700;letter-spacing:-.8px}
:root[data-design="clean-clinic"] .hero-art {display:none}
:root[data-design="modern-boutique"] .hero {border-radius:32px 8px 32px 8px}
:root[data-design="modern-boutique"] .service-card {border-left:4px solid var(--accent)}
@media(max-width:720px){.phone{width:100%;max-width:430px}.review-panel{max-width:430px}.screen{min-height:560px}}
